{
  "name": "codemirror-live-markdown",
  "version": "0.5.2-alpha.1",
  "description": "Live Preview mode for CodeMirror 6 - inspired by Obsidian",
  "type": "module",
  "main": "./dist/index.cjs",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "require": "./dist/index.cjs"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "prepare": "tsup",
    "dev": "tsup --watch",
    "build": "tsup",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:coverage": "vitest run --coverage",
    "lint": "eslint src --ext .ts",
    "format": "prettier --write \"src/**/*.ts\"",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "codemirror",
    "markdown",
    "live-preview",
    "obsidian",
    "editor",
    "wysiwyg"
  ],
  "author": "blueberrycongee",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/blueberrycongee/codemirror-live-markdown.git"
  },
  "bugs": {
    "url": "https://github.com/blueberrycongee/codemirror-live-markdown/issues"
  },
  "homepage": "https://github.com/blueberrycongee/codemirror-live-markdown#readme",
  "peerDependencies": {
    "@codemirror/lang-markdown": "^6.2.0",
    "@codemirror/language": "^6.10.0",
    "@codemirror/state": "^6.4.0",
    "@codemirror/view": "^6.24.0",
    "@lezer/markdown": "^1.2.0"
  },
  "peerDependenciesMeta": {
    "katex": {
      "optional": true
    },
    "lowlight": {
      "optional": true
    }
  },
  "devDependencies": {
    "@types/node": "^20.11.0",
    "@typescript-eslint/eslint-plugin": "^6.19.0",
    "@typescript-eslint/parser": "^6.19.0",
    "@vitest/coverage-v8": "^1.6.1",
    "eslint": "^8.56.0",
    "jsdom": "^24.1.3",
    "lowlight": "^3.3.0",
    "prettier": "^3.2.4",
    "tsup": "^8.0.1",
    "typescript": "^5.3.3",
    "vitest": "^1.2.0"
  }
}
